template <typename T, typename U>
struct MultiplyOp {
    static T execute(T a, U b) { return a * static_cast<T>(b); }
};

// Compiler generates distinct code paths for each type pairing (T, U)
float f_res = MultiplyOp<float, int>::execute(3.5f, 2);
int i_res = MultiplyOp<int, int>::execute(10, 5);

// Optimization: Eliminates runtime dispatch mechanisms (Vtables).
// Code size impact: Code bloat possible due to specialized instantiations.
